import json,csv,re,statistics as st,math,random
T=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
S={r['rating_id']:r for r in csv.DictReader(open('data/scores.csv'))}
print(len(T),len(S))
tx={}
for t in T:
    m=re.findall(r'FINAL SCORE:\s*(\d+)',t['judge_output'])
    tx[t['rating_id']]=int(m[-1])
    s=S[t['rating_id']]
    if int(s['score'])!=int(m[-1]) or s['displayed_label']!=t['displayed_label'] or len(m)!=1:
        print(t['rating_id'],t['response_id'],t['displayed_label'],s['score'],m,t['judge_output'][:200])
def eff(sc):
    d={}
    for rid,s in S.items():
        d.setdefault(s['response_id'],{})[s['displayed_label']]=sc[rid]
    diffs=[v['atlas-7']-v['nova-3'] for v in d.values()]
    return diffs
for name,sc in [('csv',{k:int(v['score']) for k,v in S.items()}),('transcript',tx)]:
    D=eff(sc);n=len(D);m=st.mean(D);sd=st.stdev(D)
    pos=sum(x>0 for x in D);neg=sum(x<0 for x in D)
    # sign-flip permutation
    random.seed(0);cnt=0;N=20000
    for _ in range(N):
        if abs(sum(x*random.choice((1,-1)) for x in D))/n>=abs(m)-1e-12: cnt+=1
    print(name,n,round(m,3),round(sd,3),'t',round(m/(sd/math.sqrt(n)),2),'CI',round(m-2.045*sd/math.sqrt(n),2),round(m+2.045*sd/math.sqrt(n),2),pos,neg,'perm p',cnt/N)
